+/** The supported language a request asks for in its Accept-Language header, else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (Array.isArray(header)) header = header.join(",");
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const wanted = [];
+  header.split(",").forEach((part, i) => {
+    const [range, ...attrs] = part.trim().split(";");
+    const tag = range.trim().toLowerCase();
+    if (!tag) return;
+    let q = 1;
+    for (const a of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(a);
+      if (m) q = Number(m[1]);
+    }
+    if (!(q > 0 && q <= 1)) return;
+    wanted.push({ lang: tag.split("-")[0], q, i });
+  });
+  wanted.sort((a, b) => b.q - a.q || a.i - b.i);
+  return wanted.find((w) => LANGUAGES.includes(w.lang))?.lang ?? fallback;
+}
